command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$branch="work/current-main-packaging-20261005"
$candidate="35cf7e53368d5f123c046b7688d0cbf6bec54b06"
$runtimeSource="a84ff56597ca638b31fdcb4a5b0bc1356cb443f3"
$expectedManifest="8ffbde6a94840cae874a761e6a26148616f167fb0db1fedb3939aa2f18968856"
$temp=Join-Path $env:RUNNER_TEMP ("current-package-final-"+$env:GITHUB_RUN_ID)
$worktreeAdded=$false
try {
  Set-Location -LiteralPath $repo
  & git fetch origin main $branch --no-tags --prune
  if($LASTEXITCODE -ne 0){throw "candidate fetch failed"}
  $observedMain=(& git rev-parse refs/remotes/origin/main).Trim()
  $observedBranch=(& git rev-parse ("refs/remotes/origin/"+$branch)).Trim()
  if($observedMain -ne $runtimeSource){throw "main moved before final package pass: $observedMain"}
  if($observedBranch -ne $candidate){throw "package candidate moved: $observedBranch"}

  if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "candidate worktree creation failed"}
  $worktreeAdded=$true
  Set-Location -LiteralPath $temp
  $env:PYTHONIOENCODING="utf-8"

  & git diff --check
  if($LASTEXITCODE -ne 0){throw "candidate diff check failed"}
  & python -X utf8 tools\winui\check_python_static.py packaging\provenance.py packaging\package.py tools\winui\diagnose_installed_shutdown.py tests\winui\test_installed_lifecycle.py tests\winui\test_installer_contract.py tests\winui\test_release_payload_contract.py
  if($LASTEXITCODE -ne 0){throw "packaging static check failed"}
  & python -X utf8 -m unittest tests.winui.test_release_payload_contract tests.winui.test_installer_contract
  if($LASTEXITCODE -ne 0){throw "packaging contract tests failed"}

  & .\build.bat Release
  if($LASTEXITCODE -ne 0){throw "canonical Release build failed"}

  & python -X utf8 packaging\provenance.py --check
  if($LASTEXITCODE -ne 0){throw "tracked current provenance does not match rebuilt runtime"}
  $provenance=Get-Content -Raw -Encoding UTF8 -LiteralPath "packaging\licenses\PAYLOAD_PROVENANCE.json" | ConvertFrom-Json
  if($provenance.runtime_source_revision -ne $runtimeSource){throw "runtime source revision mismatch"}
  if($provenance.runtime_manifest_sha256 -ne $expectedManifest){throw "runtime manifest digest changed"}

  & .\package.bat Release
  if($LASTEXITCODE -ne 0){throw "final current Release package build failed"}

  & python -X utf8 tests\winui\test_installed_lifecycle.py
  if($LASTEXITCODE -ne 0){throw "final bounded installed lifecycle failed"}

  $tracked=@(& git status --porcelain --untracked-files=no)
  if($LASTEXITCODE -ne 0){throw "failed to inspect final candidate status"}
  if($tracked.Count -ne 0){throw ("final package run changed tracked files: "+($tracked -join "; "))}

  Write-Host ("FINAL_PACKAGE_CANDIDATE="+$candidate)
  Write-Host ("FINAL_PACKAGE_RUNTIME_SOURCE="+$runtimeSource)
  Write-Host ("FINAL_PACKAGE_RUNTIME_FILES="+$provenance.runtime_file_count)
  Write-Host ("FINAL_PACKAGE_PRODUCT_FILES="+$provenance.product_generated_file_count)
  Write-Host ("FINAL_PACKAGE_NUGET_FILES="+$provenance.nuget_matched_file_count)
  Write-Host ("FINAL_PACKAGE_MANIFEST_SHA256="+$provenance.runtime_manifest_sha256)
  Write-Host "CURRENT_MAIN_FINAL_PACKAGE_ACCEPTANCE=PASS"
} finally {
  Set-Location -LiteralPath $repo
  if($worktreeAdded){
    & git worktree remove --force $temp 2>$null
    & git worktree prune
  } elseif(Test-Path -LiteralPath $temp) {
    Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue
  }
}
